CREATE TABLE IF NOT EXISTS `sites` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `name` TEXT NOT NULL, `url` TEXT NOT NULL, `platform` TEXT NOT NULL, `status` VARCHAR(191) NOT NULL DEFAULT 'active', `api_key` TEXT, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `is_pinned` BOOLEAN DEFAULT false, `sort_order` INT DEFAULT 0, `proxy_url` TEXT, `use_system_proxy` BOOLEAN DEFAULT false, `custom_headers` JSON, `external_checkin_url` TEXT, `global_weight` DOUBLE DEFAULT 1, `post_refresh_probe_enabled` BOOLEAN DEFAULT false, `post_refresh_probe_model` VARCHAR(191) DEFAULT '', `post_refresh_probe_scope` VARCHAR(191) DEFAULT 'single', `post_refresh_probe_latency_threshold_ms` INT DEFAULT 0, `codex_fingerprint_enabled` BOOLEAN DEFAULT false, `homepage_url` TEXT);
CREATE TABLE IF NOT EXISTS `accounts` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `site_id` INT NOT NULL, `username` TEXT, `access_token` TEXT NOT NULL, `api_token` TEXT, `balance` DOUBLE DEFAULT 0, `balance_used` DOUBLE DEFAULT 0, `quota` DOUBLE DEFAULT 0, `unit_cost` DOUBLE, `value_score` DOUBLE DEFAULT 0, `status` VARCHAR(191) DEFAULT 'active', `checkin_enabled` BOOLEAN DEFAULT true, `last_checkin_at` VARCHAR(191), `last_balance_refresh` VARCHAR(191), `extra_config` JSON, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `is_pinned` BOOLEAN DEFAULT false, `sort_order` INT DEFAULT 0, `oauth_provider` TEXT, `oauth_account_key` TEXT, `oauth_project_id` TEXT, `oauth_credential_payload` TEXT, `oauth_credential_version` INT NOT NULL DEFAULT 1, `oauth_refresh_state` VARCHAR(191) NOT NULL DEFAULT 'idle', `oauth_refresh_failure_count` INT NOT NULL DEFAULT 0, `oauth_refresh_retry_at` VARCHAR(191), `oauth_refresh_last_attempt_at` VARCHAR(191), `oauth_refresh_last_success_at` VARCHAR(191), `oauth_refresh_last_error` TEXT, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `account_tokens` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `account_id` INT NOT NULL, `name` TEXT NOT NULL, `token` TEXT NOT NULL, `source` VARCHAR(191) DEFAULT 'manual', `enabled` BOOLEAN DEFAULT true, `is_default` BOOLEAN DEFAULT false, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `token_group` TEXT, `value_status` VARCHAR(191) NOT NULL DEFAULT 'ready', FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `admin_auth_challenges` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `kind` TEXT NOT NULL, `token_hash` TEXT NOT NULL, `encrypted_payload` TEXT, `client_ip` TEXT, `user_agent` TEXT, `attempt_count` INT NOT NULL DEFAULT 0, `expires_at` VARCHAR(191) NOT NULL, `consumed_at` VARCHAR(191), `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')));
CREATE TABLE IF NOT EXISTS `admin_sessions` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `token_hash` TEXT NOT NULL, `csrf_token` TEXT NOT NULL, `client_ip` TEXT, `user_agent` TEXT, `expires_at` VARCHAR(191) NOT NULL, `last_seen_at` VARCHAR(191) NOT NULL, `revoked_at` VARCHAR(191), `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `second_factor_verified_at` VARCHAR(191));
CREATE TABLE IF NOT EXISTS `admin_snapshots` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `namespace` TEXT NOT NULL, `snapshot_key` TEXT NOT NULL, `payload` TEXT NOT NULL, `generated_at` VARCHAR(191) NOT NULL, `expires_at` VARCHAR(191) NOT NULL, `stale_until` VARCHAR(191) NOT NULL, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')));
CREATE TABLE IF NOT EXISTS `admin_totp_configs` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `encrypted_secret` TEXT NOT NULL, `recovery_code_hashes` TEXT NOT NULL, `last_accepted_counter` INT, `enabled_at` VARCHAR(191) NOT NULL, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')));
CREATE TABLE IF NOT EXISTS `analytics_projection_checkpoints` (`projector_key` VARCHAR(191) NOT NULL PRIMARY KEY, `time_zone` VARCHAR(191) NOT NULL DEFAULT 'Local', `last_proxy_log_id` INT NOT NULL DEFAULT 0, `watermark_created_at` VARCHAR(191), `recompute_from_id` INT, `recompute_requested_at` VARCHAR(191), `recompute_reason` TEXT, `recompute_started_at` VARCHAR(191), `recompute_completed_at` VARCHAR(191), `last_projected_at` VARCHAR(191), `last_successful_at` VARCHAR(191), `last_error` TEXT, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `lease_owner` TEXT, `lease_token` TEXT, `lease_expires_at` VARCHAR(191));
CREATE TABLE IF NOT EXISTS `local_connector_devices` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `name` TEXT NOT NULL, `platform` TEXT NOT NULL, `version` TEXT, `status` VARCHAR(191) NOT NULL DEFAULT 'active', `token_hash` TEXT NOT NULL, `scopes` TEXT NOT NULL, `capabilities` TEXT, `paired_at` VARCHAR(191) NOT NULL, `last_seen_at` VARCHAR(191), `revoked_at` VARCHAR(191), `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')));
CREATE TABLE IF NOT EXISTS `bridge_continuation_tasks` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `device_id` TEXT, `session_key` TEXT NOT NULL, `active_slot` INT, `thread_id` TEXT NOT NULL, `status` TEXT NOT NULL, `reason` TEXT NOT NULL, `policy_snapshot` JSON NOT NULL, `policy_fingerprint` TEXT NOT NULL, `continuation_count` INT NOT NULL DEFAULT 0, `started_at` VARCHAR(191) NOT NULL, `next_run_at` VARCHAR(191), `thread_status` VARCHAR(191) NOT NULL DEFAULT 'unknown', `active_flags` VARCHAR(191) NOT NULL DEFAULT '[]', `active_turn_id` TEXT, `last_failure_class` TEXT, `last_failure_source` TEXT, `last_failure_recoverability` TEXT, `last_codex_error_code` TEXT, `last_http_status_code` INT, `last_message_summary` TEXT, `last_message_fingerprint` TEXT, `last_will_retry` INT, `last_failure_turn_terminal` BOOLEAN NOT NULL DEFAULT false, `retry_after_ms` INT, `pending_route_action` TEXT, `pending_prompt` TEXT, `state_version` INT NOT NULL DEFAULT 1, `stopped_at` VARCHAR(191), `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `task_kind` VARCHAR(191) NOT NULL DEFAULT 'automatic', `submission_mode` TEXT, `pending_method` TEXT, `request_source` TEXT, `requested_by` TEXT, `source_adapter_id` TEXT, `request_idempotency_key_hash` TEXT, `prompt_fingerprint` TEXT, FOREIGN KEY (`device_id`) REFERENCES `local_connector_devices`(`id`) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS `bridge_continuation_events` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `task_id` TEXT NOT NULL, `event_type` TEXT NOT NULL, `from_status` TEXT, `to_status` TEXT NOT NULL, `reason` TEXT NOT NULL, `metadata` JSON, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `delivery_id` TEXT, FOREIGN KEY (`task_id`) REFERENCES `bridge_continuation_tasks`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `bridge_continuation_leases` (`session_key` VARCHAR(191) NOT NULL PRIMARY KEY, `task_id` TEXT NOT NULL, `owner_id` TEXT NOT NULL, `lease_token_hash` TEXT NOT NULL, `expires_at` VARCHAR(191) NOT NULL, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`task_id`) REFERENCES `bridge_continuation_tasks`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `credential_vault_items` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `site_id` INT, `account_id` INT, `name` TEXT NOT NULL, `kind` TEXT NOT NULL, `status` VARCHAR(191) NOT NULL DEFAULT 'active', `ciphertext` TEXT NOT NULL, `fingerprint` TEXT NOT NULL, `metadata` JSON, `expires_at` VARCHAR(191), `last_used_at` VARCHAR(191), `revoked_at` VARCHAR(191), `version` INT NOT NULL DEFAULT 1, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE SET NULL, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS `browser_credential_recovery_tasks` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `site_id` INT NOT NULL, `account_id` INT, `mode` TEXT NOT NULL, `status` VARCHAR(191) NOT NULL DEFAULT 'pending', `credential_name` TEXT NOT NULL, `credential_kind` VARCHAR(191) NOT NULL DEFAULT 'browser_storage', `adapter_platform` TEXT NOT NULL, `target_url` TEXT NOT NULL, `contract_snapshot` JSON NOT NULL, `task_token_hash` TEXT, `claim_token_hash` TEXT, `claimed_by` TEXT, `claimed_at` VARCHAR(191), `completed_at` VARCHAR(191), `cancelled_at` VARCHAR(191), `result_credential_id` INT, `error_code` TEXT, `error_message` TEXT, `expires_at` VARCHAR(191) NOT NULL, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE SET NULL, FOREIGN KEY (`result_credential_id`) REFERENCES `credential_vault_items`(`id`) ON DELETE SET NULL, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `checkin_logs` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `account_id` INT NOT NULL, `status` TEXT NOT NULL, `message` TEXT, `reward` TEXT, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `credential_import_jobs` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `status` VARCHAR(191) NOT NULL DEFAULT 'previewed', `target` TEXT, `site_id` INT, `operator_id` TEXT NOT NULL, `conflict_policy` VARCHAR(191) NOT NULL DEFAULT 'skip', `source_format` TEXT NOT NULL, `source_version` TEXT, `source_platform` TEXT, `detection_confidence` TEXT NOT NULL, `detection_is_batch` BOOLEAN NOT NULL DEFAULT false, `detection_warnings` TEXT, `normalization_warnings` TEXT, `batch_fingerprint` TEXT NOT NULL, `request_fingerprint` TEXT NOT NULL, `idempotency_key_hash` TEXT, `candidate_count` INT NOT NULL DEFAULT 0, `duplicate_count` INT NOT NULL DEFAULT 0, `imported_count` INT NOT NULL DEFAULT 0, `updated_count` INT NOT NULL DEFAULT 0, `skipped_count` INT NOT NULL DEFAULT 0, `failed_count` INT NOT NULL DEFAULT 0, `failure_message` TEXT, `started_at` VARCHAR(191), `completed_at` VARCHAR(191), `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS `credential_import_items` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `job_id` TEXT NOT NULL, `source_index` INT NOT NULL, `candidate_fingerprint` TEXT NOT NULL, `source_format` TEXT NOT NULL, `source_version` TEXT, `source_platform` TEXT, `provider` TEXT, `kind` TEXT NOT NULL, `identity_summary` TEXT, `secret_summary` TEXT NOT NULL, `compatible_targets` TEXT NOT NULL, `expires_at` VARCHAR(191), `disabled` BOOLEAN NOT NULL DEFAULT false, `candidate_warnings` TEXT, `validation_status` TEXT NOT NULL, `validation_errors` TEXT, `validation_warnings` TEXT, `duplicate_of_index` INT, `status` VARCHAR(191) NOT NULL DEFAULT 'previewed', `result_message` TEXT, `account_id` INT, `vault_item_ids` TEXT, `completed_at` VARCHAR(191), `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE SET NULL, FOREIGN KEY (`job_id`) REFERENCES `credential_import_jobs`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `credential_import_provenance` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `job_id` TEXT NOT NULL, `item_id` INT NOT NULL, `target_entity_type` TEXT NOT NULL, `target_entity_id` INT NOT NULL, `site_id` INT, `candidate_fingerprint` TEXT NOT NULL, `source_format` TEXT NOT NULL, `source_version` TEXT, `source_platform` TEXT, `provider` TEXT, `operator_id` TEXT NOT NULL, `conflict_policy` TEXT NOT NULL, `import_action` TEXT NOT NULL, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`item_id`) REFERENCES `credential_import_items`(`id`) ON DELETE CASCADE, FOREIGN KEY (`job_id`) REFERENCES `credential_import_jobs`(`id`) ON DELETE CASCADE, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS `downstream_api_keys` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `name` TEXT NOT NULL, `key` TEXT NOT NULL, `description` TEXT, `enabled` BOOLEAN DEFAULT true, `expires_at` VARCHAR(191), `max_cost` DOUBLE, `used_cost` DOUBLE DEFAULT 0, `max_requests` INT, `used_requests` INT DEFAULT 0, `supported_models` JSON, `allowed_route_ids` JSON, `site_weight_multipliers` JSON, `last_used_at` VARCHAR(191), `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `group_name` TEXT, `tags` TEXT, `excluded_site_ids` JSON, `excluded_credential_refs` JSON, `max_concurrency` INT, `policy_version` INT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS `downstream_api_key_leases` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `downstream_api_key_id` INT NOT NULL, `lease_token` TEXT NOT NULL, `slot` INT NOT NULL, `expires_at` VARCHAR(191) NOT NULL, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`downstream_api_key_id`) REFERENCES `downstream_api_keys`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `events` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `type` TEXT NOT NULL, `title` TEXT NOT NULL, `message` TEXT, `level` VARCHAR(191) NOT NULL DEFAULT 'info', `read` BOOLEAN DEFAULT false, `related_id` INT, `related_type` TEXT, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')));
CREATE TABLE IF NOT EXISTS `interaction_adapters` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `kind` TEXT NOT NULL, `name` TEXT NOT NULL, `enabled` BOOLEAN NOT NULL DEFAULT true, `app_id` TEXT NOT NULL, `app_secret_credential_id` INT, `verification_token_credential_id` INT, `encrypt_key_credential_id` INT, `api_base_url` VARCHAR(191) NOT NULL DEFAULT 'https://open.feishu.cn', `receive_id_type` VARCHAR(191) NOT NULL DEFAULT 'chat_id', `receive_id` TEXT NOT NULL, `console_base_url` TEXT, `operator_allowlist` VARCHAR(191) NOT NULL DEFAULT '[]', `last_dispatch_at` VARCHAR(191), `last_callback_at` VARCHAR(191), `last_error` TEXT, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `device_id` TEXT, FOREIGN KEY (`app_secret_credential_id`) REFERENCES `credential_vault_items`(`id`) ON DELETE SET NULL, FOREIGN KEY (`device_id`) REFERENCES `local_connector_devices`(`id`) ON DELETE SET NULL, FOREIGN KEY (`encrypt_key_credential_id`) REFERENCES `credential_vault_items`(`id`) ON DELETE SET NULL, FOREIGN KEY (`verification_token_credential_id`) REFERENCES `credential_vault_items`(`id`) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS `feishu_topic_bindings` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `adapter_id` TEXT NOT NULL, `device_id` TEXT NOT NULL, `codex_thread_id` TEXT NOT NULL, `root_message_id` TEXT, `feishu_thread_id` TEXT, `last_message_id` TEXT, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`adapter_id`) REFERENCES `interaction_adapters`(`id`) ON DELETE CASCADE, FOREIGN KEY (`device_id`) REFERENCES `local_connector_devices`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `interaction_prompt_cards` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `adapter_id` TEXT NOT NULL, `device_id` TEXT NOT NULL, `thread_id` TEXT NOT NULL, `context_task_id` TEXT, `status` VARCHAR(191) NOT NULL DEFAULT 'pending', `expires_at` VARCHAR(191) NOT NULL, `requested_by` TEXT NOT NULL, `request_idempotency_key_hash` TEXT NOT NULL, `request_fingerprint` TEXT NOT NULL, `consumed_task_id` TEXT, `consumed_by` TEXT, `consumed_at` VARCHAR(191), `state_version` INT NOT NULL DEFAULT 1, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`adapter_id`) REFERENCES `interaction_adapters`(`id`) ON DELETE CASCADE, FOREIGN KEY (`consumed_task_id`) REFERENCES `bridge_continuation_tasks`(`id`) ON DELETE SET NULL, FOREIGN KEY (`context_task_id`) REFERENCES `bridge_continuation_tasks`(`id`) ON DELETE SET NULL, FOREIGN KEY (`device_id`) REFERENCES `local_connector_devices`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `interaction_requests` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `device_id` TEXT NOT NULL, `source_request_key` TEXT NOT NULL, `connection_id` TEXT NOT NULL, `source_request_id` TEXT NOT NULL, `kind` TEXT NOT NULL, `method` TEXT NOT NULL, `thread_id` TEXT, `turn_id` TEXT, `item_id` TEXT, `request_payload` TEXT NOT NULL, `request_fingerprint` TEXT NOT NULL, `status` TEXT NOT NULL, `reason` TEXT NOT NULL, `response_payload` TEXT, `response_fingerprint` TEXT, `response_source` TEXT, `response_operator_id` TEXT, `response_idempotency_key_hash` TEXT, `response_committed_at` VARCHAR(191), `response_delivery_count` INT NOT NULL DEFAULT 0, `response_delivered_at` VARCHAR(191), `resolved_at` VARCHAR(191), `cancelled_at` VARCHAR(191), `expires_at` VARCHAR(191) NOT NULL, `state_version` INT NOT NULL DEFAULT 1, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`device_id`) REFERENCES `local_connector_devices`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `interaction_dispatches` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `subject_kind` VARCHAR(191) NOT NULL DEFAULT 'interaction', `interaction_id` TEXT, `prompt_card_id` TEXT, `adapter_id` TEXT NOT NULL, `status` VARCHAR(191) NOT NULL DEFAULT 'pending', `attempt_count` INT NOT NULL DEFAULT 0, `next_attempt_at` VARCHAR(191) NOT NULL, `lease_owner` TEXT, `lease_token` TEXT, `lease_expires_at` VARCHAR(191), `external_message_id` TEXT, `card_fingerprint` TEXT, `last_error` TEXT, `delivered_at` VARCHAR(191), `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`adapter_id`) REFERENCES `interaction_adapters`(`id`) ON DELETE CASCADE, FOREIGN KEY (`interaction_id`) REFERENCES `interaction_requests`(`id`) ON DELETE CASCADE, FOREIGN KEY (`prompt_card_id`) REFERENCES `interaction_prompt_cards`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `interaction_action_tickets` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `dispatch_id` TEXT NOT NULL, `interaction_id` TEXT, `prompt_card_id` TEXT, `adapter_id` TEXT NOT NULL, `action_key` TEXT NOT NULL, `token_hash` TEXT NOT NULL, `response_payload` TEXT NOT NULL, `status` VARCHAR(191) NOT NULL DEFAULT 'pending', `expires_at` VARCHAR(191) NOT NULL, `consumed_at` VARCHAR(191), `consumed_by` TEXT, `state_version` INT NOT NULL DEFAULT 1, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`adapter_id`) REFERENCES `interaction_adapters`(`id`) ON DELETE CASCADE, FOREIGN KEY (`dispatch_id`) REFERENCES `interaction_dispatches`(`id`) ON DELETE CASCADE, FOREIGN KEY (`interaction_id`) REFERENCES `interaction_requests`(`id`) ON DELETE CASCADE, FOREIGN KEY (`prompt_card_id`) REFERENCES `interaction_prompt_cards`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `interaction_card_updates` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `dispatch_id` TEXT NOT NULL, `subject_revision` INT NOT NULL, `target_status` TEXT NOT NULL, `card_fingerprint` TEXT NOT NULL, `status` VARCHAR(191) NOT NULL DEFAULT 'pending', `attempt_count` INT NOT NULL DEFAULT 0, `next_attempt_at` VARCHAR(191) NOT NULL, `deadline_at` VARCHAR(191) NOT NULL, `lease_owner` TEXT, `lease_token` TEXT, `lease_expires_at` VARCHAR(191), `last_error` TEXT, `delivered_at` VARCHAR(191), `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`dispatch_id`) REFERENCES `interaction_dispatches`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `interaction_events` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `interaction_id` TEXT NOT NULL, `delivery_id` TEXT, `event_type` TEXT NOT NULL, `from_status` TEXT, `to_status` TEXT NOT NULL, `actor_kind` TEXT NOT NULL, `actor_id` TEXT, `metadata` JSON, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`interaction_id`) REFERENCES `interaction_requests`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `local_connector_actions` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `device_id` TEXT NOT NULL, `kind` TEXT NOT NULL, `operation` TEXT NOT NULL, `status` VARCHAR(191) NOT NULL DEFAULT 'pending', `manifest` TEXT NOT NULL, `result_payload` TEXT, `backup_ref` TEXT, `error_message` TEXT, `claimed_at` VARCHAR(191), `completed_at` VARCHAR(191), `expires_at` VARCHAR(191) NOT NULL, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`device_id`) REFERENCES `local_connector_devices`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `local_connector_pairings` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `device_name` TEXT NOT NULL, `requested_scopes` TEXT NOT NULL, `token_hash` TEXT NOT NULL, `status` VARCHAR(191) NOT NULL DEFAULT 'pending', `claimed_device_id` TEXT, `expires_at` VARCHAR(191) NOT NULL, `claimed_at` VARCHAR(191), `cancelled_at` VARCHAR(191), `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`claimed_device_id`) REFERENCES `local_connector_devices`(`id`) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS `local_connector_threads` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `device_id` TEXT NOT NULL, `thread_id` TEXT NOT NULL, `thread_status` VARCHAR(191) NOT NULL DEFAULT 'unknown', `active_flags` VARCHAR(191) NOT NULL DEFAULT '[]', `active_turn_id` TEXT, `last_event_kind` TEXT NOT NULL, `last_seen_at` VARCHAR(191) NOT NULL, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `observation_source` VARCHAR(191) NOT NULL DEFAULT 'connector_app_server', `control_state` VARCHAR(191) NOT NULL DEFAULT 'available', `title` TEXT, `last_active_at` VARCHAR(191), FOREIGN KEY (`device_id`) REFERENCES `local_connector_devices`(`id`) ON DELETE CASCADE);
